"use strict";
function clamp(value, min, max) {
    return Math.min(Math.max(value, min), max);
}

"use strict";
function rot(index, modulo) {
    return (modulo + (index % modulo)) % modulo;
}

"use strict";
function formatTokenCount(count) {
    if (count >= 1_000_000) {
        const value = count / 1_000_000;
        const floored = Math.floor(value * 10) / 10;
        return floored % 1 === 0 ? `${floored.toFixed(0)}M` : `${floored.toFixed(1)}M`;
    }
    else if (count > 900_000) {
        return '1M';
    }
    else if (count >= 1000) {
        return `${Math.round(count / 1000)}K`;
    }
    return count.toString();
}

"use strict";
/**
 * The base implementation of `_.gt` which doesn't coerce arguments.
 *
 * @private
 * @param {*} value The value to compare.
 * @param {*} other The other value to compare.
 * @returns {boolean} Returns `true` if `value` is greater than `other`,
 *  else `false`.
 */
function baseGt(value, other) {
  return value > other;
}

"use strict";
/**
 * The base implementation of `_.lt` which doesn't coerce arguments.
 *
 * @private
 * @param {*} value The value to compare.
 * @param {*} other The other value to compare.
 * @returns {boolean} Returns `true` if `value` is less than `other`,
 *  else `false`.
 */
function baseLt(value, other) {
  return value < other;
}

"use strict";
/**
 * A specialized version of `_.lastIndexOf` which performs strict equality
 * comparisons of values, i.e. `===`.
 *
 * @private
 * @param {Array} array The array to inspect.
 * @param {*} value The value to search for.
 * @param {number} fromIndex The index to search from.
 * @returns {number} Returns the index of the matched value, else `-1`.
 */
function strictLastIndexOf(array, value, fromIndex) {
  var index = fromIndex + 1;
  while (index--) {
    if (array[index] === value) {
      return index;
    }
  }
  return index;
}

"use strict";
function normalizeHandlerId(id) {
  if (typeof id === 'string' && id !== '' && String(Number(id)) === id) {
    return Number(id);
  }

  return id;
}

"use strict";
function isUnsafeObjectKey(prop){return typeof prop === 'string' &&
  (prop === '__proto__' || prop === 'constructor' || prop === 'prototype');}

"use strict";
function ownedTypeOfTest(type, thing) {
  const typeOfTest = (type) => (thing) => typeof thing === type;
  const predicate = typeOfTest(type);
  return predicate(thing);
}
